from pysat.solvers import Solver
from pysat.card import CardEnc

N = 16
block_size = 4

# Fixed assignments: index -> value (1..16)
fixed = {
    5: 6, 13: 14, 14: 15, 18: 7, 22: 3, 26: 15, 27: 16, 33: 10, 34: 11,
    42: 3, 53: 10, 54: 11, 57: 6, 58: 7, 69: 5, 71: 7, 80: 6, 81: 5,
    83: 7, 84: 2, 85: 1, 94: 12, 103: 15, 106: 4, 107: 3, 109: 5,
    112: 14, 115: 15, 120: 6, 135: 6, 136: 11, 140: 15, 141: 16,
    148: 3, 150: 1, 170: 1, 175: 6, 185: 8, 188: 3, 190: 1, 196: 8,
    199: 5, 201: 11, 203: 9, 208: 8, 218: 14, 240: 16, 241: 15,
    243: 13, 244: 12, 253: 3
}

# Variable encoding: cell (i,j) has value v -> variable index = i*N*N + j*N + v
# But we can use a simpler encoding: for each cell, we have N boolean variables
# Let's use a mapping: var(i,j,v) = i*N*N + j*N + v + 1 (1-indexed for SAT solver)

def var(i, j, v):
    return i * N * N + j * N + v + 1

# Total variables: N*N*N = 16^3 = 4096
total_vars = N * N * N
print("Total variables:", total_vars)

# Create solver
s = Solver(name='g3')  # Glucose 3

# 1. Each cell must have at least one value (exactly one via cardinality)
# Actually we need exactly one value per cell. We'll encode: at least one, and at most one.

# For each cell, add clause that at least one value is true
for i in range(N):
    for j in range(N):
        clause = [var(i, j, v) for v in range(N)]
        s.add_clause(clause)

# For each cell, at most one value (pairwise encoding)
for i in range(N):
    for j in range(N):
        for v1 in range(N):
            for v2 in range(v1+1, N):
                s.add_clause([-var(i, j, v1), -var(i, j, v2)])

# 2. Each row must have each value exactly once
# For each row i and value v, exactly one column j has that value
for i in range(N):
    for v in range(N):
        clause = [var(i, j, v) for j in range(N)]
        s.add_clause(clause)
        # At most one column: pairwise
        for j1 in range(N):
            for j2 in range(j1+1, N):
                s.add_clause([-var(i, j1, v), -var(i, j2, v)])

# 3. Each column must have each value exactly once
for j in range(N):
    for v in range(N):
        clause = [var(i, j, v) for i in range(N)]
        s.add_clause(clause)
        for i1 in range(N):
            for i2 in range(i1+1, N):
                s.add_clause([-var(i1, j, v), -var(i2, j, v)])

# 4. Each block must have each value exactly once
for bi in range(block_size):
    for bj in range(block_size):
        for v in range(N):
            cells = []
            for i in range(bi*block_size, (bi+1)*block_size):
                for j in range(bj*block_size, (bj+1)*block_size):
                    cells.append(var(i, j, v))
            s.add_clause(cells)
            # At most one
            for idx1 in range(len(cells)):
                for idx2 in range(idx1+1, len(cells)):
                    s.add_clause([-cells[idx1], -cells[idx2]])

# 5. Fixed assignments
for idx, val in fixed.items():
    i = idx // N
    j = idx % N
    v = val - 1  # 0-indexed
    s.add_clause([var(i, j, v)])

print("Clauses added, solving...")
status = s.solve()
print("Status:", status)

if status:
    model = s.get_model()
    # model is a list of literals; positive means true, negative means false
    # We need to extract the true variables
    solution = [0] * (N * N)
    for lit in model:
        if lit > 0:
            # var index = lit
            idx = lit - 1
            v = idx % N
            j = (idx // N) % N
            i = idx // (N * N)
            if i < N and j < N:
                solution[i * N + j] = v + 1
    print("Solution found")
    # Verify
    ok = True
    for idx, val in fixed.items():
        if solution[idx] != val:
            print(f"Mismatch at {idx}: expected {val}, got {solution[idx]}")
            ok = False
    if ok:
        print("All fixed values match")
    # Print grid
    for i in range(N):
        print(' '.join(f'{solution[i*N+j]:2d}' for j in range(N)))
else:
    print("UNSAT")
    solution = None
